import pytest
import tenacity
from flaky import flaky


@pytest.mark.flaky(reruns=3)
def test_a():
    assert 1


@pytest.mark.flaky
def test_b():
    assert 1


@flaky(max_runs=3)
def test_c():
    assert 1


@tenacity.retry(
    stop=tenacity.stop_after_attempt(3),
)  # try again
@pytest.mark.slow
async def test_d():
    assert 1

